/**
 * Represents whether a block has directional shapes in Minecraft Legends.
 *
 * This type specifies whether the block's shape changes based on its orientation. It allows developers
 * to define visually and functionally dynamic blocks.
 *
 * type {boolean} BlockDirectionalShapeType
 * @category Block Configuration
 * @example
 * const directionalShape: BlockDirectionalShapeType = true;
 * @remarks
 * Properly configuring this setting ensures that directional shapes are applied correctly.
 * Misconfigured settings may lead to visual or functional inconsistencies.
 */
declare type BlockDirectionalShapeType = boolean;
